<?php
$esc=function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};$message=(string)$this->getParam('message','');$error=(string)$this->getParam('error','');
echo '<div class="skin-workspace certificate-workspace"><header class="skin-workspace__header"><h1>'.$this->language->languageText('mod_certificate_service_title','certificate-service').'</h1><p>'.$this->language->languageText('mod_certificate_service_intro','certificate-service').'</p></header>';
if($message!==''){echo '<p class="confirm">'.$this->language->languageText('mod_certificate_service_'.$message,'certificate-service').'</p>';}if($error!==''){echo '<p class="error">'.$this->language->languageText('mod_certificate_service_'.$error,'certificate-service').'</p>';}
if($certificateIsAdmin){echo '<div class="skin-workspace__grid"><section class="skin-card"><h2>'.$this->language->languageText('mod_certificate_service_bases','certificate-service').'</h2><form method="post" enctype="multipart/form-data" action="'.$this->uri(array('action'=>'createbase')).'">';foreach(array('name'=>'basename','organisation'=>'organisation','company_name'=>'companyname','company_location'=>'location','website_url'=>'website') as $name=>$key){echo '<label>'.$this->language->languageText('mod_certificate_service_'.$key,'certificate-service').'<input type="text" name="'.$name.'"'.(in_array($name,array('name','organisation','company_name'),true)?' required':'').'></label>';}echo '<label>'.$this->language->languageText('mod_certificate_service_logo','certificate-service').'<input type="file" name="logo" accept="image/png,image/jpeg"></label><div class="certificate-colours"><label>'.$this->language->languageText('mod_certificate_service_primarycolour','certificate-service').'<input type="color" name="primary_colour" value="#1f2937"></label><label>'.$this->language->languageText('mod_certificate_service_accentcolour','certificate-service').'<input type="color" name="accent_colour" value="#b49352"></label></div><input type="hidden" name="csrf_token" value="'.$esc($certificateCsrf).'"><button class="button" type="submit">'.$this->language->languageText('mod_certificate_service_savebase','certificate-service').'</button></form></section>';
echo '<section class="skin-card"><h2>'.$this->language->languageText('mod_certificate_service_signers','certificate-service').'</h2><form method="post" enctype="multipart/form-data" action="'.$this->uri(array('action'=>'createsigner')).'"><label>'.$this->language->languageText('mod_certificate_service_signername','certificate-service').'<input type="text" name="name" required></label><label>'.$this->language->languageText('mod_certificate_service_signertitle','certificate-service').'<input type="text" name="title"></label><label>'.$this->language->languageText('mod_certificate_service_signature','certificate-service').'<input type="file" name="signature" accept="image/png,image/jpeg"></label><input type="hidden" name="csrf_token" value="'.$esc($certificateCsrf).'"><button class="button" type="submit">'.$this->language->languageText('mod_certificate_service_savesigner','certificate-service').'</button></form></section></div>';}
if($certificateContextCode!==''){echo '<section class="skin-card certificate-course"><h2>'.$this->language->languageText('mod_certificate_service_assigncourse','certificate-service').'</h2><form method="post" action="'.$this->uri(array('action'=>'assigncourse')).'"><label>'.$this->language->languageText('mod_certificate_service_choosebase','certificate-service').'<select name="base_id" required><option value=""></option>';foreach($certificateBases as $base){echo '<option value="'.$esc($base['id']).'"'.($certificateAssignment&&$certificateAssignment['base_id']===$base['id']?' selected':'').'>'.$esc($base['name']).'</option>';}echo '</select></label><label>'.$this->language->languageText('mod_certificate_service_choosesigner','certificate-service').'<select name="signer_id" required><option value=""></option>';foreach($certificateSigners as $signer){echo '<option value="'.$esc($signer['id']).'"'.($certificateAssignment&&$certificateAssignment['signer_id']===$signer['id']?' selected':'').'>'.$esc($signer['name']).'</option>';}echo '</select></label><input type="hidden" name="csrf_token" value="'.$esc($certificateCsrf).'"><button class="button" type="submit">'.$this->language->languageText('mod_certificate_service_assign','certificate-service').'</button></form></section>';}
echo '</div><style>.certificate-workspace{max-width:86rem;margin:0 auto}.certificate-workspace .skin-workspace__grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}.certificate-workspace .skin-card{padding:1.5rem}.certificate-workspace form{display:grid;gap:1rem}.certificate-workspace label{display:grid;gap:.35rem;font-weight:600}.certificate-workspace input,.certificate-workspace select{box-sizing:border-box;width:100%;padding:.7rem;border:1px solid #ccd3da;border-radius:.35rem}.certificate-colours{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.certificate-course{margin-top:1.5rem}@media(max-width:48rem){.certificate-workspace .skin-workspace__grid{grid-template-columns:1fr}}</style>';
?>
